 ```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      max-width: 800px;
      margin: 0 auto;
      padding: 1rem;
      background: #f8f9fa;
      color: #212529;
    }
    h1, h2 { margin-top: 0; }
    section {
      background: #fff;
      border: 1px solid #dee2e6;
      border-radius: 6px;
      padding: 1rem;
      margin-bottom: 1rem;
    }
    label {
      display: block;
      margin-bottom: 0.25rem;
      font-weight: 600;
    }
    input, select {
      width: 100%;
      padding: 0.5rem;
      margin-bottom: 0.75rem;
      border: 1px solid #ced4da;
      border-radius: 4px;
      font-size: 1rem;
    }
    button {
      padding: 0.5rem 1rem;
      font-size: 1rem;
      border: none;
      border-radius: 4px;
      cursor: pointer;
    }
    #add-expense {
      background: #0d6efd;
      color: #fff;
    }
    #add-expense:hover { background: #0b5ed7; }
    #form-error {
      color: #dc3545;
      margin-top: 0.5rem;
      min-height: 1.25rem;
    }
    .filters { display: grid; gap: 0.75rem; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); }
    .summary { display: flex; flex-wrap: wrap; gap: 1rem; align-items: baseline; }
    #total { font-size: 1.5rem; font-weight: 700; }
    .cat-total {
      background: #e9ecef;
      padding: 0.35rem 0.65rem;
      border-radius: 4px;
      font-weight: 600;
    }
    table { width: 100%; border-collapse: collapse; margin-top: 0.5rem; }
    th, td { text-align: left; padding: 0.6rem; border-bottom: 1px solid #dee2e6; }
    th { background: #f1f3f5; font-weight: 600; }
    .expense.hidden { display: none; }
    .exp-del {
      background: #dc3545;
      color: #fff;
      padding: 0.35rem 0.7rem;
      font-size: 0.9rem;
    }
    .exp-del:hover { background: #bb2d3b; }
    .note { color: #6c757d; font-size: 0.9rem; }
  </style>
</head>
<body>
  <h1>Personal Expense Tracker</h1>

  <section>
    <h2>Add Expense</h2>
    <form id="expense-form">
      <label for="amount">Amount</label>
      <input type="number" id="amount" step="0.01" placeholder="0.00" />

      <label for="category">Category</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>

      <label for="date">Date</label>
      <input type="date" id="date" />

      <label for="note">Note (optional)</label>
      <input type="text" id="note" placeholder="Optional note" />

      <button type="submit" id="add-expense">Add Expense</button>
      <div id="form-error"></div>
    </form>
  </section>

  <section>
    <h2>Filters</h2>
    <div class="filters">
      <div>
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">All</option>
          <option value="groceries">Groceries</option>
          <option value="transport">Transport</option>
          <option value="bills">Bills</option>
          <option value="fun">Fun</option>
        </select>
      </div>
      <div>
        <label for="filter-from">From</label>
        <input type="date" id="filter-from" />
      </div>
      <div>
        <label for="filter-to">To</label>
        <input type="date" id="filter-to" />
      </div>
    </div>
  </section>

  <section>
    <h2>Summary</h2>
    <div class="summary">
      <span>Total: $<span id="total">0.00</span></span>
      <div id="category-summary"></div>
    </div>
  </section>

  <section>
    <h2>Expenses</h2>
    <table>
      <thead>
        <tr>
          <th>Category</th>
          <th>Amount</th>
          <th>Date</th>
          <th>Note</th>
          <th></th>
        </tr>
      </thead>
      <tbody id="expense-list"></tbody>
    </table>
  </section>

  <script>
    const STORAGE_KEY = 'personal-expense-tracker';
    let expenses = [];

    const amountInput = document.getElementById('amount');
    const categoryInput = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteInput = document.getElementById('note');
    const formError = document.getElementById('form-error');
    const expenseForm = document.getElementById('expense-form');

    const filterCategory = document.getElementById('filter-category');
    const filterFrom = document.getElementById('filter-from');
    const filterTo = document.getElementById('filter-to');

    const totalEl = document.getElementById('total');
    const categorySummaryEl = document.getElementById('category-summary');
    const expenseListEl = document.getElementById('expense-list');

    const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

    function saveExpenses() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    }

    function loadExpenses() {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) expenses = JSON.parse(data);
      } catch (e) {
        expenses = [];
      }
    }

    function formatMoney(value) {
      return value.toFixed(2);
    }

    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    function capitalize(str) {
      return str.charAt(0).toUpperCase() + str.slice(1);
    }

    function renderRows() {
      expenseListEl.innerHTML = '';
      const sorted = expenses.slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

      sorted.forEach(expense => {
        const row = document.createElement('tr');
        row.className = 'expense';
        row.dataset.category = expense.category;
        row.dataset.date = expense.date;
        row.dataset.amount = expense.amount.toFixed(2);

        row.innerHTML = `
          <td>${escapeHtml(expense.category)}</td>
          <td>${formatMoney(expense.amount)}</td>
          <td>${expense.date}</td>
          <td class="note">${escapeHtml(expense.note || '')}</td>
          <td><button class="exp-del" data-id="${expense.id}">Delete</button></td>
        `;

        expenseListEl.appendChild(row);
      });

      document.querySelectorAll('.exp-del').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.dataset.id;
          expenses = expenses.filter(e => e.id !== id);
          saveExpenses();
          applyFilters();
        });
      });

      applyFilters();
    }

    function applyFilters() {
      const category = filterCategory.value;
      const from = filterFrom.value;
      const to = filterTo.value;

      let visibleTotal = 0;
      const catTotals = {};
      CATEGORIES.forEach(c => catTotals[c] = 0);

      document.querySelectorAll('.expense').forEach(row => {
        const rowCat = row.dataset.category;
        const rowDate = row.dataset.date;
        const rowAmount = parseFloat(row.dataset.amount);

        const matchesCategory = category === 'all' || rowCat === category;
        const matchesFrom = !from || rowDate >= from;
        const matchesTo = !to || rowDate <= to;
        const matches = matchesCategory && matchesFrom && matchesTo;

        row.classList.toggle('hidden', !matches);

        if (matches) {
          visibleTotal += rowAmount;
          if (catTotals.hasOwnProperty(rowCat)) {
            catTotals[rowCat] += rowAmount;
          }
        }
      });

      totalEl.textContent = formatMoney(visibleTotal);

      categorySummaryEl.innerHTML = '';
      CATEGORIES.forEach(cat => {
        const el = document.createElement('div');
        el.className = 'cat-total';
        el.dataset.cat = cat;
        el.textContent = `${capitalize(cat)}: $${formatMoney(catTotals[cat])}`;
        categorySummaryEl.appendChild(el);
      });
    }

    expenseForm.addEventListener('submit', (event) => {
      event.preventDefault();

      const rawAmount = amountInput.value.trim();
      const amount = parseFloat(rawAmount);
      const date = dateInput.value;
      const category = categoryInput.value;
      const note = noteInput.value.trim();

      if (
        rawAmount === '' ||
        Number.isNaN(amount) ||
        !isFinite(amount) ||
        amount <= 0 ||
        date === ''
      ) {
        formError.textContent = 'Please enter a valid positive amount and a date.';
        return;
      }

      formError.textContent = '';

      const newExpense = {
        id: Date.now().toString(),
        amount: amount,
        category: category,
        date: date,
        note: note,
        createdAt: Date.now()
      };

      expenses.push(newExpense);
      saveExpenses();
      amountInput.value = '';
      renderRows();
    });

    filterCategory.addEventListener('change', applyFilters);
    filterFrom.addEventListener('change', applyFilters);
    filterTo.addEventListener('change', applyFilters);

    loadExpenses();
    renderRows();
  </script>
</body>
</html>
```
